import json

class TextFileProcessor:

    def __init__(self, file_path):
        self.file_path = file_path

    def read_file_as_json(self):
        """Read the self.file_path file as json format.
        if the file content doesn't obey json format, the code will raise error.
        :return data: dict if the file is stored as json format, or str/int/float.. according to the file content otherwise.
        """
        try:
            with open(self.file_path, 'r') as file:
                content = file.read()
                if not content.strip():
                    raise ValueError('File is empty')
                data = json.loads(content)
                return data
        except FileNotFoundError:
            raise FileNotFoundError(f'The file at {self.file_path} does not exist.')
        except json.JSONDecodeError:
            raise ValueError(f'The file at {self.file_path} is not a valid JSON file.')

    def read_file(self):
        """Read the return the content of self.file_path file.
        :return: the same return as the read() method
        """
        try:
            with open(self.file_path, 'r', encoding='utf-8') as file:
                content = file.read()
            return content
        except FileNotFoundError:
            raise FileNotFoundError(f'The file at {self.file_path} does not exist.')
        except PermissionError:
            raise PermissionError(f'Permission denied to read the file at {self.file_path}.')
        except IOError as e:
            raise IOError(f'An error occurred while reading the file: {e}')

    def write_file(self, content):
        """Write content into the self.file_path file, and overwrite if the file has already existed.
        :param content: any content
        """
        if content is None:
            raise ValueError('Content cannot be None')
        try:
            with open(self.file_path, 'w') as file:
                file.write(str(content))
        except IOError as e:
            raise IOError(f'Failed to write to file: {self.file_path}. Error: {e}')
        except PermissionError as e:
            raise PermissionError(f'Permission denied to write to file: {self.file_path}. Error: {e}')
        except TypeError as e:
            raise TypeError(f'Content must be a string or convertible to string. Error: {e}')

    def process_file(self):
        try:
            with open(self.file_path, 'r') as file:
                content = file.read()
            processed_content = ''.join(filter(str.isalpha, content))
            with open(self.file_path, 'w') as file:
                file.write(processed_content)
        except FileNotFoundError:
            raise FileNotFoundError(f"The file '{self.file_path}' does not exist.")
        except Exception as e:
            raise Exception(f'An error occurred while processing the file: {e}')

